package io.metersphere.agent.service;

import io.metersphere.agent.constants.AgentTokenScope;
import io.metersphere.agent.security.AgentTokenContext;
import io.metersphere.sdk.exception.MSException;
import io.metersphere.system.domain.AgentToken;
import io.metersphere.system.utils.SessionUtils;
import org.junit.jupiter.api.*;
import org.mockito.MockedStatic;
import org.springframework.mock.env.MockEnvironment;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

/** Real role/source/ACL SQL and durable version ledger; catalog byte parsing is a separate integration seam. */
class AgentKnowledgeGovernanceTests extends AgentProtocolTransactionTests {
    AgentKnowledgeService knowledge;AgentProtocolAccess access;AgentBusinessAccess business;AgentSessionProtocolConfiguration config;MockedStatic<SessionUtils> human;
    @BeforeEach void knowledgeFixture(){
        jdbc.execute("CREATE TABLE project(id VARCHAR(64) PRIMARY KEY,organization_id VARCHAR(64),enable INT,deleted INT)");
        jdbc.execute("CREATE TABLE user(id VARCHAR(64) PRIMARY KEY,enable INT,deleted INT)");jdbc.execute("CREATE TABLE user_role(id VARCHAR(64) PRIMARY KEY,enabled INT,type VARCHAR(32))");jdbc.execute("CREATE TABLE user_role_relation(user_id VARCHAR(64),role_id VARCHAR(64),source_id VARCHAR(64))");jdbc.execute("CREATE TABLE user_role_permission(role_id VARCHAR(64),permission_id VARCHAR(128))");
        jdbc.execute("CREATE TABLE agent_token(id VARCHAR(64) PRIMARY KEY,user_id VARCHAR(64),enable BOOLEAN,status VARCHAR(32),revoked_at BIGINT,expire_time BIGINT,scopes VARCHAR(1024),project_ids VARCHAR(1024))");
        jdbc.execute("CREATE TABLE ai_source_document(id VARCHAR(64) PRIMARY KEY,project_id VARCHAR(64),deleted INT)");jdbc.execute("CREATE TABLE test_asset_version(id VARCHAR(64) PRIMARY KEY,project_id VARCHAR(64),asset_type VARCHAR(32),asset_id VARCHAR(64),content_hash VARCHAR(64),content_snapshot TEXT)");
        jdbc.update("INSERT INTO project VALUES ('p1','org',1,0),('p2','org',1,0),('foreign-project','foreign',1,0)");jdbc.update("INSERT INTO user VALUES ('u1',1,0),('u2',1,0),('u3',1,0)");jdbc.update("INSERT INTO user_role VALUES ('r1',1,'PROJECT'),('r2',1,'PROJECT')");jdbc.update("INSERT INTO user_role_relation VALUES ('u1','r1','p1'),('u1','r2','p2'),('u2','r1','p1'),('u2','r2','p2'),('u3','r1','p1')");jdbc.update("INSERT INTO user_role_permission VALUES ('r1','FUNCTIONAL_CASE_AI:READ'),('r2','FUNCTIONAL_CASE_AI:READ')");
        for(int i=1;i<=3;i++){jdbc.update("INSERT INTO agent_token VALUES (?,?,true,'ACTIVE',NULL,NULL,?,'[\"p1\",\"p2\"]')","t"+i,"u"+i,AgentProtocolData.encode(List.of(AgentTokenScope.KNOWLEDGE_READ_V1,AgentTokenScope.KNOWLEDGE_EDIT_V1)));jdbc.update("INSERT INTO msp_protocol_subject VALUES (?,'org',?,?,true,1)","t"+i,"u"+i,"agent-"+i);}
        for(String capability:List.of("KNOWLEDGE_EDIT","KNOWLEDGE_PUBLISH"))jdbc.update("INSERT INTO msp_protocol_grant VALUES ('org','u1','env',?,?,1)",capability,System.currentTimeMillis()+60000);
        jdbc.update("INSERT INTO ai_source_document VALUES ('a','p1',0),('b','p2',0)");jdbc.update("INSERT INTO test_asset_version VALUES ('va','p1','DOCUMENT','a','hash-a','{}'),('vb','p2','DOCUMENT','b','hash-b','{}')");
        var environment=new MockEnvironment();byte[] fixtureKey=new byte[32];new java.security.SecureRandom().nextBytes(fixtureKey);environment.setProperty("agent.execution.facts-key",Base64.getEncoder().encodeToString(fixtureKey));for(String key:List.of("knowledge-enabled"))environment.setProperty(AgentSessionProtocolConfiguration.PREFIX+key,"true");for(String key:List.of("limits.title-scalars","limits.body-scalars","limits.reference-scalars","limits.content-utf8-bytes"))environment.setProperty(AgentSessionProtocolConfiguration.PREFIX+key,"100000");for(String key:List.of("approval.version","approval.record","retention.policy-version","retention.approval-record","retention.capacity-evidence","retention.reference-protection-evidence"))environment.setProperty(AgentSessionProtocolConfiguration.PREFIX+key,"isolated-test-approval");
        config=new AgentSessionProtocolConfiguration(environment);business=new AgentBusinessAccess(jdbc);access=new AgentProtocolAccess(jdbc,business);knowledge=new AgentKnowledgeService(jdbc,store,access,business,config,mock(TestAssetCatalogService.class));agent(1);
    }
    @AfterEach void identityCleanup(){if(human!=null)human.close();AgentTokenContext.clear();}
    void agent(int index){if(human!=null){human.close();human=null;}var token=new AgentToken();token.setId("t"+index);token.setUserId("u"+index);AgentTokenContext.set(token);}
    void human(){AgentTokenContext.clear();human=mockStatic(SessionUtils.class);human.when(SessionUtils::getUserId).thenReturn("u1");human.when(SessionUtils::getCurrentOrganizationId).thenReturn("org");}
    Map<String,Object> source(String project,String id,String version,String hash){return Map.of("projectId",project,"assetType","DOCUMENT","assetId",id,"versionId",version,"snapshotHash",hash,"contributes",true);}
    Map<String,Object> content(){return new LinkedHashMap<>(Map.of("schemaVersion","1.0","title","Shared controlled method","type","OPERATION","body","Business procedure","scope","test only","preconditions","not needed","successCriteria","authoritative object exists","relations",List.of(),"sources",List.of(source("p1","a","va","hash-a"),source("p2","b","vb","hash-b"))));}
    Map<String,Object> draft(Map<String,Object> content){return knowledge.save("org",Map.of("idempotencyKey",UUID.randomUUID().toString(),"environmentId","env","content",content));}
    Map<String,Object> publish(Map<String,Object> draft,List<String> readers){return knowledge.govern("org","publish",Map.of("idempotencyKey","publish-"+draft.get("knowledgeId"),"knowledgeId",draft.get("knowledgeId"),"expectedKnowledgeVersion",draft.get("version"),"environmentId","env","readers",readers,"reason","fixture verified"));}
    @Test void sourceIntersectionIsRecheckedForSearchHistoricalReadAndSuccessfulReceiptReplay(){
        var draft=draft(content());human();publish(draft,List.of("u1","u2"));agent(2);assertEquals(1,knowledge.search("org","",1,20).get("total"));assertEquals(draft.get("knowledgeId"),knowledge.get("org",(String)draft.get("knowledgeId"),1L).get("id"));
        jdbc.update("DELETE FROM user_role_relation WHERE user_id='u2' AND source_id='p2'");assertEquals(0,knowledge.search("org","",1,20).get("total"));assertThrows(MSException.class,()->knowledge.get("org",(String)draft.get("knowledgeId"),1L));
        agent(1);var update=new LinkedHashMap<>(content());update.put("body","new draft");var request=Map.<String,Object>of("idempotencyKey","update-original","knowledgeId",draft.get("knowledgeId"),"expectedKnowledgeVersion",1,"environmentId","env","content",update);knowledge.save("org",request);jdbc.update("DELETE FROM user_role_relation WHERE user_id='u1' AND source_id='p2'");assertThrows(MSException.class,()->knowledge.save("org",request));
    }
    @Test void draftNeverBecomesAdoptableByVersionNumberAndHumanPublicationIsIdempotent(){
        var draft=draft(content());assertThrows(MSException.class,()->knowledge.get("org",(String)draft.get("knowledgeId"),1L));assertThrows(MSException.class,()->knowledge.fixed("org",(String)draft.get("knowledgeId"),1,access.knowledgeActor("org",false),true));
        assertEquals("PROTOCOL_HUMAN_REQUIRED",assertThrows(MSException.class,()->publish(draft,List.of("u1"))).getMessage());human();var first=publish(draft,List.of("u1"));assertEquals(true,publish(draft,List.of("u1")).get("replayed"));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM msp_knowledge_version WHERE state='PUBLISHED'",Integer.class));assertEquals("PUBLISHED",first.get("state"));
    }
    @Test void ordinaryDisablePreservesFixedHistoricalUseButSafetyRevocationBlocksIt(){
        var draft=draft(content());human();publish(draft,List.of("u1"));knowledge.govern("org","disable",Map.of("idempotencyKey","disable","knowledgeId",draft.get("knowledgeId"),"expectedKnowledgeVersion",1,"environmentId","env","reason","stop new adoption"));agent(1);var actor=access.knowledgeActor("org",false);assertDoesNotThrow(()->knowledge.fixed("org",(String)draft.get("knowledgeId"),1,actor,false));assertThrows(MSException.class,()->knowledge.fixed("org",(String)draft.get("knowledgeId"),1,actor,true));human();knowledge.govern("org","revoke",Map.of("idempotencyKey","revoke","knowledgeId",draft.get("knowledgeId"),"expectedKnowledgeVersion",2,"environmentId","env","reason","unsafe method"));agent(1);assertThrows(MSException.class,()->knowledge.fixed("org",(String)draft.get("knowledgeId"),1,actor,false));
    }
    @Test void missingNaturalPersonMappingDoesNotBlockKnowledgeReadingButCannotEnterExecutionIdentity(){
        var draft=draft(content());human();publish(draft,List.of("u1"));agent(1);assertNotNull(knowledge.get("org",(String)draft.get("knowledgeId"),null));assertThrows(MSException.class,()->access.actor("org",false));
    }
    @Test void publicationCannotExpandPastSourceAclOrPersistSecretsAsPublished(){
        var draft=draft(content());human();assertThrows(MSException.class,()->publish(draft,List.of("u1","u3")));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM msp_knowledge_version WHERE state='PUBLISHED'",Integer.class));
        agent(1);var secret=content();secret.put("body","password=do-not-publish");var unsafe=draft(secret);human();assertEquals("PROTOCOL_SENSITIVE_CONTENT",assertThrows(MSException.class,()->publish(unsafe,List.of("u1"))).getMessage());assertEquals("DRAFT",jdbc.queryForObject("SELECT state FROM msp_knowledge WHERE id=?",String.class,unsafe.get("knowledgeId")));
    }
    @Test void contributionCannotBeRemovedToLaunderAccessAndCrossOrganizationIsRejected(){var draft=draft(content());var laundered=content();laundered.put("sources",List.of(source("p1","a","va","hash-a")));assertThrows(MSException.class,()->knowledge.save("org",Map.of("idempotencyKey","launder","knowledgeId",draft.get("knowledgeId"),"expectedKnowledgeVersion",1,"environmentId","env","content",laundered)));var foreign=content();foreign.put("sources",List.of(source("foreign-project","a","va","hash-a")));assertThrows(MSException.class,()->draft(foreign));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM msp_knowledge",Integer.class));}

    @Test void formalSyncRechecksLiveReviewerGrantsAndContributorIdentityMappings(){
        jdbc.update("INSERT INTO user_role_permission VALUES ('r1','FUNCTIONAL_CASE:READ')");for(String capability:List.of("RESULT_REVIEW","VERIFY_EXTERNAL","EVIDENCE_READ"))jdbc.update("INSERT INTO msp_protocol_grant VALUES ('org','u1','env',?,?,1)",capability,System.currentTimeMillis()+60000);
        jdbc.update("INSERT INTO msp_protocol_identity VALUES ('u1','org','reviewer',1,'fixture'),('u2','org','executor',1,'fixture'),('u3','org','author',1,'fixture')");var session=Map.<String,Object>of("organization_id","org","environment_id","env","project_id","p1");var data=Map.<String,Object>of("reviewerUserId","u1","reviewerPerson","reviewer","executorIdentities",Map.of("u2","executor"),"evidenceIdentities",Map.of(),"executorPersons",List.of("executor"),"evidencePersons",List.of(),"contract",Map.of("authorUserId","u3","authorPerson","author"));
        store.transaction(()->{access.requireAcceptedReviewer(session,data);return null;});jdbc.update("UPDATE msp_protocol_identity SET person_ref='reviewer' WHERE user_id='u2'");assertThrows(MSException.class,()->store.transaction(()->{access.requireAcceptedReviewer(session,data);return null;}));jdbc.update("UPDATE msp_protocol_identity SET person_ref='executor' WHERE user_id='u2'");jdbc.update("DELETE FROM msp_protocol_grant WHERE capability='VERIFY_EXTERNAL'");assertThrows(MSException.class,()->store.transaction(()->{access.requireAcceptedReviewer(session,data);return null;}));
    }
    @Test void migrationSeparatesSnapshotParsingFromOriginalVerificationAndKeepsPerItemFailures(){
        jdbc.execute("ALTER TABLE test_asset_version ADD source_version VARCHAR(64)");String good="{\"body\":\"historical self report\"}",bad="{invalid";jdbc.update("UPDATE test_asset_version SET content_snapshot=?,content_hash=?,source_version='run-good' WHERE id='va'",good,org.apache.commons.codec.digest.DigestUtils.sha256Hex(good));jdbc.update("UPDATE test_asset_version SET content_snapshot=?,content_hash=?,source_version='run-bad' WHERE id='vb'",bad,org.apache.commons.codec.digest.DigestUtils.sha256Hex(bad));
        var env=(org.springframework.mock.env.MockEnvironment)org.springframework.test.util.ReflectionTestUtils.getField(config,"environment");env.setProperty(AgentSessionProtocolConfiguration.PREFIX+"migration-enabled","true");env.setProperty(AgentSessionProtocolConfiguration.PREFIX+"migration.batch-size","10");env.setProperty(AgentSessionProtocolConfiguration.PREFIX+"limits.import-bytes","100000");var catalog=mock(TestAssetCatalogService.class);var document=new io.metersphere.agent.dto.TestAssetCatalogItemDTO();document.setName("historical document");when(catalog.detail(anyString(),eq("DOCUMENT"),anyString())).thenReturn(document);var migration=new AgentKnowledgeMigrationService(jdbc,store,access,catalog,knowledge,config);
        var preview=migration.preview("p1","a","va");assertEquals("PARSED",preview.get("parseStatus"));assertEquals(false,preview.get("originalDownloadVerified"));assertEquals("FAILED",migration.preview("p2","b","vb").get("parseStatus"));
        var request=Map.<String,Object>of("batchId","fixture-batch","environmentId","env","cursor",0,"previewOnly",false,"sources",List.of(Map.of("projectId","p1","assetId","a","versionId","va"),Map.of("projectId","p2","assetId","b","versionId","vb")));var result=migration.migrate("org",request);assertEquals(2,AgentProtocolData.objects(result.get("records")).size());assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM msp_knowledge WHERE state='CANDIDATE'",Integer.class));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM msp_protocol_migration WHERE state='FAILED'",Integer.class));migration.migrate("org",request);assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM msp_knowledge",Integer.class));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM msp_knowledge_version WHERE state='PUBLISHED'",Integer.class));assertEquals(2,jdbc.queryForObject("SELECT COUNT(*) FROM test_asset_version",Integer.class));
    }

    @Test void taskHandoffAuthorizationBindsTrustedHumanProofToTheRealAttemptAndLease(){
        jdbc.execute("ALTER TABLE ai_execution_step_result ADD task_id VARCHAR(64)");jdbc.execute("ALTER TABLE ai_execution_step_result ADD execution_id VARCHAR(64)");for(String column:List.of("current_execution_id VARCHAR(64)","runner_lease_id VARCHAR(64)","status VARCHAR(32)","blocked_reason VARCHAR(64)","version INT DEFAULT 0","update_time BIGINT"))jdbc.execute("ALTER TABLE ai_execution_task ADD "+column);jdbc.update("UPDATE ai_execution_task SET project_id='p1',current_execution_id='attempt',runner_lease_id='lease',status='PREPARING_BROWSER'");jdbc.execute("CREATE TABLE ai_runner_lease(id VARCHAR(64),task_id VARCHAR(64),execution_id VARCHAR(64),status VARCHAR(32),executor_channel VARCHAR(64),expire_time BIGINT,version INT DEFAULT 0,update_time BIGINT)");jdbc.update("INSERT INTO ai_runner_lease VALUES ('lease','task','attempt','ACTIVE','EXTERNAL_MCP_AGENT',?,0,1)",System.currentTimeMillis()+60000);jdbc.update("INSERT INTO user_role_permission VALUES ('r1','FUNCTIONAL_CASE:READ'),('r1','FUNCTIONAL_CASE:READ+UPDATE'),('r1','AI_EXECUTION:READ'),('r1','AI_EXECUTION:RUN')");jdbc.update("INSERT INTO msp_protocol_identity VALUES ('u1','org','human-authorizer',1,'fixture')");jdbc.update("INSERT INTO msp_protocol_grant VALUES ('org','u1','env','AUTHORIZE_TASK',?,1)",System.currentTimeMillis()+60000);jdbc.update("INSERT INTO msp_protocol_policy VALUES ('org','env',1,true,?)",store.payload(Map.of("allowedActions",List.of("DELETE"),"actionRules",Map.of("DELETE",Map.of("effect","DELETE","entity","owned")))));human();var service=new AgentProtocolPolicyService(jdbc,store,access,config);var args=new LinkedHashMap<String,Object>(Map.of("environmentId","env","expectedVersion",0,"allowedActions",List.of("DELETE"),"expiresAt",System.currentTimeMillis()+60000,"mutationsOwnDataOnly",true,"reason","trusted task handoff"));args.putAll(Map.of("handoffExecutionId","attempt","handoffLeaseId","wrong-lease","handoffEvidenceRef","authority-proof","handoffAuthorityQuery","independent source query confirmed no unresolved legacy business operation"));assertEquals("PROTOCOL_SOURCE_HANDOFF_REQUIRED",assertThrows(MSException.class,()->service.authorize("p1","TASK","task",args)).getMessage());assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM msp_protocol_authorization",Integer.class));args.put("handoffLeaseId","lease");service.authorize("p1","TASK","task",args);var clearance=AgentProtocolData.object(service.authorization("org","env","TASK","task",false).get("handoffClearance"));assertEquals("attempt",clearance.get("executionId"));assertEquals("lease",clearance.get("leaseId"));assertEquals("u1",clearance.get("authorizer"));assertEquals(1L,((Number)service.currentAuthorization("p1","TASK","task","env").get("version")).longValue());args.put("expectedVersion",1);service.authorize("p1","TASK","task",args);assertEquals(2L,((Number)service.currentAuthorization("p1","TASK","task","env").get("version")).longValue());store.transaction(()->{access.requireAuthorizationSigner("u1","human-authorizer","p1","org","env");return null;});jdbc.update("DELETE FROM msp_protocol_grant WHERE capability='AUTHORIZE_TASK'");assertThrows(MSException.class,()->store.transaction(()->{access.requireAuthorizationSigner("u1","human-authorizer","p1","org","env");return null;}));assertEquals("PAUSED",jdbc.queryForObject("SELECT status FROM ai_execution_task",String.class));assertEquals("RELEASED",jdbc.queryForObject("SELECT status FROM ai_runner_lease",String.class));assertEquals("PROTOCOL_HANDOFF_VERIFIED",jdbc.queryForObject("SELECT blocked_reason FROM ai_execution_task",String.class));
    }
}
